-- 0005 — money, change, shift-link and enum invariants enforced by the DATABASE.
--
-- Closes, at the database level, invariants that until now only service code held
-- (proposal 0007 §3 I2, I3, I7, I8, I11). A service bug, a repair script or a psql session
-- could otherwise write a payment with a zero amount, an unknown method, change that does not
-- reconcile, or a shift_id pointing at ANOTHER tenant's shift.
--
-- Generated by `npm run db:generate` from engines/transactions/src/db/schema.ts.
-- Do not hand-edit: change the schema and regenerate.
--
-- Scope: this migration touches ONLY the tables introduced in 0003 plus their shift links.
-- It deliberately does NOT constrain `sales_transactions`, `transaction_lines` or
-- `cash_movements` — that is the wider G-4 decision (owner), tracked in STATUS.md §6.
ALTER TABLE "payments" ADD CONSTRAINT "payments_shift_fk" FOREIGN KEY ("tenant_id","shift_id") REFERENCES "public"."cash_shifts"("tenant_id","id") ON DELETE no action ON UPDATE no action;--> statement-breakpoint
ALTER TABLE "refunds" ADD CONSTRAINT "refunds_shift_fk" FOREIGN KEY ("tenant_id","shift_id") REFERENCES "public"."cash_shifts"("tenant_id","id") ON DELETE no action ON UPDATE no action;--> statement-breakpoint
ALTER TABLE "cash_movement_resolutions" ADD CONSTRAINT "cash_movement_resolutions_kind" CHECK ("cash_movement_resolutions"."resolution" in ('posted', 'returned'));--> statement-breakpoint
ALTER TABLE "cash_shift_closures" ADD CONSTRAINT "cash_shift_closures_counted_nonneg" CHECK ("cash_shift_closures"."counted_minor" >= 0);--> statement-breakpoint
ALTER TABLE "cash_shift_closures" ADD CONSTRAINT "cash_shift_closures_difference_adds_up" CHECK ("cash_shift_closures"."difference_minor" = "cash_shift_closures"."counted_minor" - "cash_shift_closures"."expected_minor");--> statement-breakpoint
ALTER TABLE "cash_shifts" ADD CONSTRAINT "cash_shifts_opening_nonneg" CHECK ("cash_shifts"."opening_minor" >= 0);--> statement-breakpoint
ALTER TABLE "payments" ADD CONSTRAINT "payments_amount_positive" CHECK ("payments"."amount_minor" > 0);--> statement-breakpoint
ALTER TABLE "payments" ADD CONSTRAINT "payments_method_known" CHECK ("payments"."method" in ('cash', 'card', 'wallet', 'transfer'));--> statement-breakpoint
ALTER TABLE "payments" ADD CONSTRAINT "payments_tender_identity" CHECK ("payments"."change_minor" is null or ("payments"."tendered_minor" is not null and "payments"."tendered_minor" - "payments"."change_minor" = "payments"."amount_minor"));--> statement-breakpoint
ALTER TABLE "refunds" ADD CONSTRAINT "refunds_amount_positive" CHECK ("refunds"."amount_minor" > 0);